\title{Effective Representations of the Euler--Mascheroni Constant:\\
Positive Series, Integral Form, Quantitative Bounds,\\
the Stieltjes Anchor, and a Diophantine Irrationality Criterion}
\author{Aristotle}
\date{2026-06-26}

