function gamma_integral(N, m):
    total <- 0
    for k from 0 to N-1:
        a <- k+1; b <- k+2; h <- (b-a)/m; c <- 1/(k+1)
        acc <- 0
        for j from 0 to m-1:
            x <- a + (j + 0.5)*h
            acc <- acc + (c - 1/x)
        total <- total + acc*h        # ~ g_k
    return total                       # -> gamma as N -> infinity
